import{z as i,x as A,o as r,c as d,q as s,j as o,D as B,d as e,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"最长前缀匹配","description":"","frontmatter":{"title":"最长前缀匹配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lpm.md","filePath":"cs/lpm.md","lastUpdated":1791413859000}'),p={name:"cs/lpm.md"};function C(D,a,m,c,T,P){const t=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=s('<h1 id="最长前缀匹配" tabindex="-1">最长前缀匹配 <a class="header-anchor" href="#最长前缀匹配" aria-label="Permalink to &quot;最长前缀匹配&quot;">​</a></h1><div class="epigraph"><p>路由表里多条前缀都能对上目的地址时，选前缀最长的那一条；那是最具体的网络。</p><footer>—— 据 Fuller 等, RFC 1519, Classless Inter-Domain Routing；RFC 4632 整理</footer></div><p><a href="/cs/cidr-agg">上一课</a>给出前缀与「是否直连」。一张表里同时有 <code>10.0.0.0/8</code> 与 <code>10.1.2.0/24</code> 时，目的 <code>10.1.2.9</code> 两条都匹配。缺口是<strong>最长前缀匹配（LPM）</strong>：CIDR 下的查找规则。本课不把硬件 TCAM 结构写完，也不引入 BGP 策略。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分类地址曾用首几位决定类，查找简单但粗。CIDR 允许任意长度前缀，路由聚合才压得住全球表。聚合后必须保留「例外更具体」：一个 /16 里挖出的 /24 走另一下一跳。缺口不是 ARP，而是比较匹配前缀的长度，最长者胜；都没有则默认路由 <code>/0</code>。</p><p>本课不把 trie 压缩的论文细节当必背。</p><p><span class="marginnote">术语翻译：「最长」指的是共同前缀的<strong>比特数</strong>。目的地址 \\(10.1.2.9\\) 同时落在 \\(10.0.0.0/8\\)（前 8 位相同）与 \\(10.1.2.0/24\\)（前 24 位相同）里，24 比特比 8 比特更具体，故选 /24——像寄快递「浙江省→杭州市→西湖区某街道」，门牌越细越优先。</span></p><p><span class="marginnote">等价：把地址与前缀掩码逐条与，在命中者中选掩码一比特最多的。实现用树或 TCAM 并行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>转发表：若干 (前缀, 下一跳, 出接口)。查找：LPM 得下一跳，再对该接口 <a href="/cs/arp">ARP</a>（或已缓存）。主机上的「默认网关」就是一条 <code>/0</code>。多条等长前缀若下一跳不同，属于等价多路径，本课只点名，不把哈希分流写完。</p><p><span class="marginnote">常见误区：初学者容易以为路由查找是「找一条完全相等的表项」。转发表存的是前缀（一段网络），目的地址只要以该比特串开头就算命中，一条 /8 表项覆盖一千六百多万个地址；所以「多条同时命中、挑最长」才是常态而非异常。</span></p>',11)),(r(),o(n,null,{default:B(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADDR%5B%22%E7%9B%AE%E7%9A%84%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20MATCH%5B%22%E6%89%80%E6%9C%89%E5%8C%B9%E9%85%8D%E5%89%8D%E7%BC%80%22%5D%0A%20%20MATCH%20--%3E%20LPM%5B%22%E9%80%89%E6%9C%80%E9%95%BF%E8%80%85%22%5D%0A%20%20LPM%20--%3E%20NH%5B%22%E4%B8%8B%E4%B8%80%E8%B7%B3%E4%B8%8E%E5%87%BA%E6%8E%A5%E5%8F%A3%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("LPM 让互联网可以分层编号又保留例外，这是后课链路状态与 BGP 填表时默认的查找语义。与"),E("a",{href:"/cs/paging-vm"},"页表"),e("的多级翻译不同：那里是固定切分虚地址；这里前缀长度可变。不要把 LPM 说成页表。TTL 用尽在本课仍不解释 ICMP，只承认包会被丢。")],-1)),a[5]||(a[5]=E("p",null,"端到端：LPM 选错下一跳是配置问题，IP 不重试另一条，除非路由协议改表。传输层会当丢包。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"为什么重要：更具体的黑洞路由能靠最长匹配压过较宽的正常通告——一条 /32 丢弃路由就能让某台主机的包「无声消失」。IP 层不重试，传输层只看到超时，排查时第一步是确认命中的到底是哪条前缀。")],-1)),(r(),o(n,null,{default:B(()=>[l(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22trie%20%E6%9F%A5%E6%89%BE%EF%BC%9A%E6%8C%89%E5%9C%B0%E5%9D%80%E4%BD%8D%E9%80%90%E4%BD%8D%E4%B8%8B%E8%A1%8C%22%5D%20--%3E%20HIT%5B%22%E6%AF%8F%E7%BB%8F%E8%BF%87%E4%B8%80%E4%B8%AA%E5%89%8D%E7%BC%80%E8%8A%82%E7%82%B9%E8%AE%B0%E4%B8%BA%E5%BD%93%E5%89%8D%E5%80%99%E9%80%89%22%5D%0A%20%20HIT%20--%3E%20END%5B%22%E6%97%A0%E6%B3%95%E7%BB%A7%E7%BB%AD%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20END%20--%3E%20OUT%5B%22%E6%9C%80%E8%BF%91%E7%9A%84%E5%80%99%E9%80%89%E8%83%9C%E5%87%BA%20%3D%20%E6%9C%80%E9%95%BF%E5%8C%B9%E9%85%8D%22%5D%0A%20%20ROOT%20--%3E%20NOHIT%5B%22%E4%B8%80%E8%B7%AF%E6%9C%AA%E7%BB%8F%E8%BF%87%E4%BB%BB%E4%BD%95%E5%89%8D%E7%BC%80%E8%8A%82%E7%82%B9%22%5D%0A%20%20NOHIT%20--%3E%20DEF%7B%22%E8%A1%A8%E4%B8%AD%E5%AD%98%E5%9C%A8%20%2F0%20%3F%22%7D%0A%20%20DEF%20--%3E%7C%22%E6%9C%89%22%7C%20GOTAKE%5B%22%E8%B5%B0%E9%BB%98%E8%AE%A4%E8%B7%AF%E7%94%B1%22%5D%0A%20%20DEF%20--%3E%7C%22%E6%97%A0%22%7C%20ICMP%5B%22%E6%97%A0%E8%B7%AF%E7%94%B1%EF%BC%9A%E4%B8%A2%E5%BC%83%E5%B9%B6%E6%8A%A5%E4%B8%8D%E5%8F%AF%E8%BE%BE%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SRv6 与策略路由的全部选择器（源地址、标记）。不把 TCAM 功耗写成体系结构课。控制平面如何算出这些前缀，是距离向量与链路状态的缺口；本课假定表已经在。</p><p>默认路由与「没有路由」不同：前者匹配一切，后者才触发 ICMP 不可达。主机可以只有默认，路由器通常还要直连。</p><p>更具体的黑洞路由（丢弃）也靠最长匹配压过较宽的通告，运维上要小心顺序。</p><p>后课默认：转发查找是 LPM。包无法投递或 TTL 用尽时，网络层要向源报告，下一课 ICMP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CIDR 下多匹配时取最长前缀。</li><li>默认路由是长度为 0 的前缀。</li><li>控制平面填表是后课；不可达报告是 ICMP。</li><li>出处：RFC 1519；RFC 4632；Kurose and Ross。</li></ul>',7))])}const h=i(p,[["render",C]]);export{F as __pageData,h as default};
